from fractions import Fraction

ND = 2
UNITS = [("feroke", 1, 16, (0, 1)), ("kukufe", 100, 1, (0, 1)), ("miti", 1, 1, (0, 1)), ("rohuba", 25, 2, (1, 0)), ("safe", 1, 1, (1, 0))]
DIGITS = 3
HAS_POW = False
ZERO = (0,) * ND


class CalcError(Exception):
    pass


def tokenize(s):
    toks = []
    i = 0
    dg = "0123456789"
    while i < len(s):
        c = s[i]
        if c in " \t":
            i += 1
        elif c in dg:
            j = i
            while j < len(s) and s[j] in dg:
                j += 1
            if j < len(s) and s[j] == ".":
                k = j + 1
                if k >= len(s) or s[k] not in dg:
                    raise CalcError("syntax")
                while k < len(s) and s[k] in dg:
                    k += 1
                j = k
            toks.append(("num", s[i:j]))
            i = j
        elif "a" <= c <= "z":
            j = i
            while j < len(s) and "a" <= s[j] <= "z":
                j += 1
            toks.append(("id", s[i:j]))
            i = j
        elif c in "+-*/()" or (c == "^" and HAS_POW):
            toks.append((c, c))
            i += 1
        else:
            raise CalcError("syntax")
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0] if self.i < len(self.t) else None

    def take(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expr(self):
        left = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()[0]
            left = (op, left, self.term())
        return left

    def term(self):
        left = self.unary()
        while self.peek() in ("*", "/"):
            op = self.take()[0]
            left = (op, left, self.unary())
        return left

    def unary(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.unary())
        return self.power()

    def exp(self):
        if HAS_POW and self.peek() == "^":
            self.take()
            sign = 1
            if self.peek() == "-":
                self.take()
                sign = -1
            if self.peek() != "num":
                raise CalcError("syntax")
            txt = self.take()[1]
            if len(txt) != 1:
                raise CalcError("syntax")
            return sign * int(txt)
        return None

    def power(self):
        k = self.peek()
        if k == "num":
            txt = self.take()[1]
            if "." in txt:
                a, b = txt.split(".")
                val = Fraction(int(a + b), 10 ** len(b))
            else:
                val = Fraction(int(txt))
            if self.peek() == "id":
                name = self.take()[1]
                return ("qty", val, name, self.exp())
            e = self.exp()
            return ("npow", val, e) if e is not None else ("num", val)
        if k == "id":
            name = self.take()[1]
            return ("unit", name, self.exp())
        if k == "(":
            self.take()
            inner = self.expr()
            if self.peek() != ")":
                raise CalcError("syntax")
            self.take()
            e = self.exp()
            return ("pow", inner, e) if e is not None else inner
        raise CalcError("syntax")


def parse(s):
    p = Parser(tokenize(s))
    tree = p.expr()
    if p.i != len(p.t):
        raise CalcError("syntax")
    return tree


def powq(v, e):
    r, d = v
    if e < 0:
        if r == 0:
            raise CalcError("divide by zero")
        return (Fraction(1) / r) ** (-e), tuple(x * e for x in d)
    return r ** e, tuple(x * e for x in d)


def unit(name):
    for n, num, den, dims in UNITS:
        if n == name:
            return Fraction(num, den), dims
    raise CalcError("unknown unit " + name)


def ev(t):
    k = t[0]
    if k == "num":
        return t[1], ZERO
    if k == "npow":
        return powq((t[1], ZERO), t[2])
    if k == "unit":
        f, d = unit(t[1])
        return powq((f, d), t[2]) if t[2] is not None else (f, d)
    if k == "qty":
        f, d = unit(t[2])
        f, d = powq((f, d), t[3]) if t[3] is not None else (f, d)
        return t[1] * f, d
    if k == "pow":
        return powq(ev(t[1]), t[2])
    if k == "neg":
        r, d = ev(t[1])
        return -r, d
    a = ev(t[1])
    b = ev(t[2])
    if k in "+-":
        if a[1] != b[1]:
            raise CalcError("dimension")
        return (a[0] + b[0] if k == "+" else a[0] - b[0]), a[1]
    if k == "*":
        return a[0] * b[0], tuple(x + y for x, y in zip(a[1], b[1]))
    if b[0] == 0:
        raise CalcError("divide by zero")
    return a[0] / b[0], tuple(x - y for x, y in zip(a[1], b[1]))


def fmt(q):
    neg = q < 0
    q = abs(q)
    scale = 10 ** DIGITS
    scaled = (2 * q.numerator * scale + q.denominator) // (2 * q.denominator)
    ip, fp = divmod(scaled, scale)
    s = str(ip)
    if fp:
        s += "." + str(fp).rjust(DIGITS, "0").rstrip("0")
    return ("-" + s) if (neg and scaled != 0) else s


def evaluate(expr):
    return ev(parse(expr))


def calc(expr, target):
    try:
        r, d = evaluate(expr)
        if target == "-":
            if d != ZERO:
                raise CalcError("dimension")
            return fmt(r)
        f, td = unit(target)
        if td != d:
            raise CalcError("dimension")
        return fmt(r / f) + " " + target
    except CalcError as e:
        return "error: " + str(e)

