use unitcalc::calc;

#[test]
fn cases() {
    let cases: Vec<(Vec<&str>, &str)> = vec![
        (vec!["4 wizu + 1 wizu", "sasuhu"], "0.4167 sasuhu"),
        (vec!["26 fehu", "fehu"], "26 fehu"),
        (vec!["1.5 sasuhu", "wizu"], "18 wizu"),
    ];
    for (i, (a, want)) in cases.iter().enumerate() {
        let got = calc(a[0], a[1]);
        assert_eq!(got, *want, "case {} {:?}", i, a);
    }
}

solution.unitcalc.go:
package unitcalc

import (
	"math/big"
	"strconv"
	"strings"
)

const (
	nd      = 3
	digits  = 4
	hasPow  = true
)

type unitDef struct {
	name     string
	num, den int64
	dims     [nd]int
}

var units = []unitDef{{"dasu", 12, 1, [nd]int{0, 1, 0}}, {"fera", 100, 1, [nd]int{0, 0, 1}}, {"kufe", 1, 1, [nd]int{0, 1, 0}}, {"loke", 1, 1, [nd]int{1, 0, 0}}, {"pavovo", 1, 16, [nd]int{1, 0, 0}}, {"rawi", 1, 1, [nd]int{0, 0, 1}}, {"suro", 12, 1, [nd]int{0, 1, 0}}, {"suyoyo", 1, 16, [nd]int{0, 0, 1}}, {"wizu", 1, 3, [nd]int{1, 0, 0}}, {"yonemi", 2, 1, [nd]int{0, -1, 1}}}

type calcErr struct{ msg string }

func fail(m string) { panic(calcErr{m}) }

type value struct {
	r    *big.Rat
	dims [nd]int
}

type tok struct{ kind, text string }

func isDig(c byte) bool { return c >= '0' && c <= '9' }

func tokenize(s string) []tok {
	var out []tok
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t':
			i++
		case isDig(c):
			j := i
			for j < len(s) && isDig(s[j]) {
				j++
			}
			if j < len(s) && s[j] == '.' {
				k := j + 1
				if k >= len(s) || !isDig(s[k]) {
					fail("syntax")
				}
				for k < len(s) && isDig(s[k]) {
					k++
				}
				j = k
			}
			out = append(out, tok{"num", s[i:j]})
			i = j
		case c >= 'a' && c <= 'z':
			j := i
			for j < len(s) && s[j] >= 'a' && s[j] <= 'z' {
				j++
			}
			out = append(out, tok{"id", s[i:j]})
			i = j
		case strings.IndexByte("+-*/()", c) >= 0 || (c == '^' && hasPow):
			out = append(out, tok{string(c), string(c)})
			i++
		default:
			fail("syntax")
		}
	}
	return out
}

type node struct {
	kind string // num npow unit qty pow neg + - * /
	val  *big.Rat
	name string
	exp  *int
	a, b *node
}

type parser struct {
	t []tok
	i int
}

func (p *parser) peek() string {
	if p.i < len(p.t) {
		return p.t[p.i].kind
	}
	return ""
}

func (p *parser) take() tok {
	t := p.t[p.i]
	p.i++
	return t
}

func (p *parser) exp() *int {
	if hasPow && p.peek() == "^" {
		p.take()
		sign := 1
		if p.peek() == "-" {
			p.take()
			sign = -1
		}
		if p.peek() != "num" {
			fail("syntax")
		}
		txt := p.take().text
		if len(txt) != 1 {
			fail("syntax")
		}
		v, _ := strconv.Atoi(txt)
		v *= sign
		return &v
	}
	return nil
}

func parseNum(txt string) *big.Rat {
	r := new(big.Rat)
	if i := strings.IndexByte(txt, '.'); i >= 0 {
		frac := txt[i+1:]
		n, _ := new(big.Int).SetString(txt[:i]+frac, 10)
		d := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(len(frac))), nil)
		return r.SetFrac(n, d)
	}
	n, _ := new(big.Int).SetString(txt, 10)
	return r.SetInt(n)
}

func (p *parser) power() *node {
	switch p.peek() {
	case "num":
		val := parseNum(p.take().text)
		if p.peek() == "id" {
			name := p.take().text
			return &node{kind: "qty", val: val, name: name, exp: p.exp()}
		}
		if e := p.exp(); e != nil {
			return &node{kind: "npow", val: val, exp: e}
		}
		return &node{kind: "num", val: val}
	case "id":
		name := p.take().text
		return &node{kind: "unit", name: name, exp: p.exp()}
	case "(":
		p.take()
		inner := p.expr()
		if p.peek() != ")" {
			fail("syntax")
		}
		p.take()
		if e := p.exp(); e != nil {
			return &node{kind: "pow", a: inner, exp: e}
		}
		return inner
	}
	fail("syntax")
	return nil
}

func (p *parser) unary() *node {
	if p.peek() == "-" {
		p.take()
		return &node{kind: "neg", a: p.unary()}
	}
	return p.power()
}

func (p *parser) term() *node {
	left := p.unary()
	for p.peek() == "*" || p.peek() == "/" {
		op := p.take().kind
		left = &node{kind: op, a: left, b: p.unary()}
	}
	return left
}

func (p *parser) expr() *node {
	left := p.term()
	for p.peek() == "+" || p.peek() == "-" {
		op := p.take().kind
		left = &node{kind: op, a: left, b: p.term()}
	}
	return left
}

func powq(v value, e int) value {
	out := value{r: new(big.Rat).SetInt64(1)}
	base := new(big.Rat).Set(v.r)
	n := e
	if e < 0 {
		if v.r.Sign() == 0 {
			fail("divide by zero")
		}
		base.Inv(base)
		n = -e
	}
	for k := 0; k < n; k++ {
		out.r.Mul(out.r, base)
	}
	for i := range v.dims {
		out.dims[i] = v.dims[i] * e
	}
	return out
}

func lookup(name string) value {
	for _, u := range units {
		if u.name == name {
			return value{r: big.NewRat(u.num, u.den), dims: u.dims}
		}
	}
	fail("unknown unit " + name)
	return value{}
}

func ev(t *node) value {
	switch t.kind {
	case "num":
		return value{r: t.val}
	case "npow":
		return powq(value{r: t.val}, *t.exp)
	case "unit":
		u := lookup(t.name)
		if t.exp != nil {
			return powq(u, *t.exp)
		}
		return u
	case "qty":
		u := lookup(t.name)
		if t.exp != nil {
			u = powq(u, *t.exp)
		}
		return value{r: new(big.Rat).Mul(t.val, u.r), dims: u.dims}
	case "pow":
		return powq(ev(t.a), *t.exp)
	case "neg":
		a := ev(t.a)
		return value{r: new(big.Rat).Neg(a.r), dims: a.dims}
	}
	a := ev(t.a)
	b := ev(t.b)
	switch t.kind {
	case "+", "-":
		if a.dims != b.dims {
			fail("dimension")
		}
		if t.kind == "+" {
			return value{r: new(big.Rat).Add(a.r, b.r), dims: a.dims}
		}
		return value{r: new(big.Rat).Sub(a.r, b.r), dims: a.dims}
	case "*":
		out := value{r: new(big.Rat).Mul(a.r, b.r)}
		for i := range out.dims {
			out.dims[i] = a.dims[i] + b.dims[i]
		}
		return out
	}
	if b.r.Sign() == 0 {
		fail("divide by zero")
	}
	out := value{r: new(big.Rat).Quo(a.r, b.r)}
	for i := range out.dims {
		out.dims[i] = a.dims[i] - b.dims[i]
	}
	return out
}

func format(q *big.Rat) string {
	neg := q.Sign() < 0
	n := new(big.Int).Abs(q.Num())
	d := q.Denom()
	scale := new(big.Int).Exp(big.NewInt(10), big.NewInt(digits), nil)
	scaled := new(big.Int).Mul(n, scale)
	scaled.Mul(scaled, big.NewInt(2))
	scaled.Add(scaled, d)
	scaled.Div(scaled, new(big.Int).Mul(d, big.NewInt(2)))
	ip, fp := new(big.Int).DivMod(scaled, scale, new(big.Int))
	s := ip.String()
	if fp.Sign() != 0 {
		f := fp.String()
		f = strings.Repeat("0", digits-len(f)) + f
		s += "." + strings.TrimRight(f, "0")
	}
	if neg && scaled.Sign() != 0 {
		return "-" + s
	}
	return s
}

// Calc evaluates expr and renders it in the target unit ("-" for a plain number).
func Calc(expr, target string) (out string) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(calcErr); ok {
				out = "error: " + e.msg
				return
			}
			panic(r)
		}
	}()
	p := &parser{t: tokenize(expr)}
	tree := p.expr()
	if p.i != len(p.t) {
		fail("syntax")
	}
	v := ev(tree)
	var zero [nd]int
	if target == "-" {
		if v.dims != zero {
			fail("dimension")
		}
		return format(v.r)
	}
	u := lookup(target)
	if u.dims != v.dims {
		fail("dimension")
	}
	return format(new(big.Rat).Quo(v.r, u.r)) + " " + target
}

