solution.src/lib.rs:
const ND: usize = 3;
const DIGITS: u32 = 2;
const HAS_POW: bool = true;
const UNITS: &[(&str, i128, i128, [i32; ND])] = &[("bayo", 12, 1, [0, 0, 1]), ("gomi", 9, 4, [0, 1, 0]), ("hubapa", 12, 1, [0, 1, 0]), ("kesu", 1, 16, [1, 0, 0]), ("milo", 5, 4, [2, -1, 0]), ("rafe", 1, 1, [0, 0, 1]), ("sagoba", 1, 16, [0, 0, 1]), ("suyoba", 1, 1, [1, 0, 0]), ("tisuzu", 1, 1, [0, 1, 0]), ("tiwi", 100, 1, [0, 0, 1]), ("wihuda", 9, 4, [1, 0, 0])];

type Dims = [i32; ND];

#[derive(Clone, Copy)]
struct Q {
    n: i128,
    d: i128,
}

fn gcd(a: i128, b: i128) -> i128 {
    let (mut a, mut b) = (a.abs(), b.abs());
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

fn q(n: i128, d: i128) -> Q {
    let g = gcd(n, d).max(1);
    let s = if d < 0 { -1 } else { 1 };
    Q { n: s * n / g, d: s * d / g }
}

impl Q {
    fn add(self, o: Q) -> Q { q(self.n * o.d + o.n * self.d, self.d * o.d) }
    fn sub(self, o: Q) -> Q { q(self.n * o.d - o.n * self.d, self.d * o.d) }
    fn mul(self, o: Q) -> Q { q(self.n * o.n, self.d * o.d) }
    fn div(self, o: Q) -> Q { q(self.n * o.d, self.d * o.n) }
}

#[derive(Clone)]
enum Tok {
    Num(String),
    Id(String),
    Sym(char),
}

enum Node {
    Num(Q),
    NPow(Q, i32),
    Unit(String, Option<i32>),
    Qty(Q, String, Option<i32>),
    Pow(Box<Node>, i32),
    Neg(Box<Node>),
    Bin(char, Box<Node>, Box<Node>),
}

type R<T> = Result<T, String>;

fn syntax<T>() -> R<T> {
    Err("syntax".to_string())
}

fn tokenize(s: &str) -> R<Vec<Tok>> {
    let b: Vec<char> = s.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    let dg = |c: char| c.is_ascii_digit();
    while i < b.len() {
        let c = b[i];
        if c == ' ' || c == '\t' {
            i += 1;
        } else if dg(c) {
            let mut j = i;
            while j < b.len() && dg(b[j]) {
                j += 1;
            }
            if j < b.len() && b[j] == '.' {
                let mut k = j + 1;
                if k >= b.len() || !dg(b[k]) {
                    return syntax();
                }
                while k < b.len() && dg(b[k]) {
                    k += 1;
                }
                j = k;
            }
            out.push(Tok::Num(b[i..j].iter().collect()));
            i = j;
        } else if c.is_ascii_lowercase() {
            let mut j = i;
            while j < b.len() && b[j].is_ascii_lowercase() {
                j += 1;
            }
            out.push(Tok::Id(b[i..j].iter().collect()));
            i = j;
        } else if "+-*/()".contains(c) || (c == '^' && HAS_POW) {
            out.push(Tok::Sym(c));
            i += 1;
        } else {
            return syntax();
        }
    }
    Ok(out)
}

struct Parser {
    t: Vec<Tok>,
    i: usize,
}

impl Parser {
    fn peek_sym(&self, c: char) -> bool {
        matches!(self.t.get(self.i), Some(Tok::Sym(x)) if *x == c)
    }
    fn exp(&mut self) -> R<Option<i32>> {
        if HAS_POW && self.peek_sym('^') {
            self.i += 1;
            let mut sign = 1;
            if self.peek_sym('-') {
                self.i += 1;
                sign = -1;
            }
            match self.t.get(self.i).cloned() {
                Some(Tok::Num(txt)) => {
                    self.i += 1;
                    if txt.len() != 1 {
                        return syntax();
                    }
                    Ok(Some(sign * txt.parse::<i32>().unwrap()))
                }
                _ => syntax(),
            }
        } else {
            Ok(None)
        }
    }
    fn power(&mut self) -> R<Node> {
        match self.t.get(self.i).cloned() {
            Some(Tok::Num(txt)) => {
                self.i += 1;
                let val = parse_num(&txt);
                if let Some(Tok::Id(name)) = self.t.get(self.i).cloned() {
                    self.i += 1;
                    let e = self.exp()?;
                    return Ok(Node::Qty(val, name, e));
                }
                match self.exp()? {
                    Some(e) => Ok(Node::NPow(val, e)),
                    None => Ok(Node::Num(val)),
                }
            }
            Some(Tok::Id(name)) => {
                self.i += 1;
                let e = self.exp()?;
                Ok(Node::Unit(name, e))
            }
            Some(Tok::Sym('(')) => {
                self.i += 1;
                let inner = self.expr()?;
                if !self.peek_sym(')') {
                    return syntax();
                }
                self.i += 1;
                match self.exp()? {
                    Some(e) => Ok(Node::Pow(Box::new(inner), e)),
                    None => Ok(inner),
                }
            }
            _ => syntax(),
        }
    }
    fn unary(&mut self) -> R<Node> {
        if self.peek_sym('-') {
            self.i += 1;
            return Ok(Node::Neg(Box::new(self.unary()?)));
        }
        self.power()
    }
    fn term(&mut self) -> R<Node> {
        let mut left = self.unary()?;
        while self.peek_sym('*') || self.peek_sym('/') {
            let op = if self.peek_sym('*') { '*' } else { '/' };
            self.i += 1;
            let right = self.unary()?;
            left = Node::Bin(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }
    fn expr(&mut self) -> R<Node> {
        let mut left = self.term()?;
        while self.peek_sym('+') || self.peek_sym('-') {
            let op = if self.peek_sym('+') { '+' } else { '-' };
            self.i += 1;
            let right = self.term()?;
            left = Node::Bin(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }
}

fn parse_num(txt: &str) -> Q {
    match txt.find('.') {
        Some(i) => {
            let frac = &txt[i + 1..];
            let n: i128 = format!("{}{}", &txt[..i], frac).parse().unwrap();
            q(n, 10i128.pow(frac.len() as u32))
        }
        None => q(txt.parse().unwrap(), 1),
    }
}

fn powq(v: (Q, Dims), e: i32) -> R<(Q, Dims)> {
    let (r, d) = v;
    let mut base = r;
    let mut n = e;
    if e < 0 {
        if r.n == 0 {
            return Err("divide by zero".to_string());
        }
        base = q(r.d, r.n);
        n = -e;
    }
    let mut out = q(1, 1);
    for _ in 0..n {
        out = out.mul(base);
    }
    let mut nd = d;
    for x in nd.iter_mut() {
        *x *= e;
    }
    Ok((out, nd))
}

fn unit(name: &str) -> R<(Q, Dims)> {
    for (n, num, den, dims) in UNITS.iter() {
        if *n == name {
            return Ok((q(*num, *den), *dims));
        }
    }
    Err(format!("unknown unit {}", name))
}

fn ev(t: &Node) -> R<(Q, Dims)> {
    let zero: Dims = [0; ND];
    match t {
        Node::Num(v) => Ok((*v, zero)),
        Node::NPow(v, e) => powq((*v, zero), *e),
        Node::Unit(name, e) => {
            let u = unit(name)?;
            match e {
                Some(e) => powq(u, *e),
                None => Ok(u),
            }
        }
        Node::Qty(v, name, e) => {
            let mut u = unit(name)?;
            if let Some(e) = e {
                u = powq(u, *e)?;
            }
            Ok((v.mul(u.0), u.1))
        }
        Node::Pow(inner, e) => powq(ev(inner)?, *e),
        Node::Neg(inner) => {
            let a = ev(inner)?;
            Ok((q(-a.0.n, a.0.d), a.1))
        }
        Node::Bin(op, l, r) => {
            let a = ev(l)?;
            let b = ev(r)?;
            match op {
                '+' | '-' => {
                    if a.1 != b.1 {
                        return Err("dimension".to_string());
                    }
                    Ok((if *op == '+' { a.0.add(b.0) } else { a.0.sub(b.0) }, a.1))
                }
                '*' => {
                    let mut d = a.1;
                    for i in 0..ND {
                        d[i] += b.1[i];
                    }
                    Ok((a.0.mul(b.0), d))
                }
                _ => {
                    if b.0.n == 0 {
                        return Err("divide by zero".to_string());
                    }
                    let mut d = a.1;
                    for i in 0..ND {
                        d[i] -= b.1[i];
                    }
                    Ok((a.0.div(b.0), d))
                }
            }
        }
    }
}

fn fmt(v: Q) -> String {
    let neg = v.n < 0;
    let n = v.n.abs();
    let scale = 10i128.pow(DIGITS);
    let scaled = (2 * n * scale + v.d) / (2 * v.d);
    let (ip, fp) = (scaled / scale, scaled % scale);
    let mut s = ip.to_string();
    if fp != 0 {
        let f = format!("{:0w$}", fp, w = DIGITS as usize);
        s.push('.');
        s.push_str(f.trim_end_matches('0'));
    }
    if neg && scaled != 0 {
        format!("-{}", s)
    } else {
        s
    }
}

fn run(expr: &str, target: &str) -> R<String> {
    let toks = tokenize(expr)?;
    let mut p = Parser { t: toks, i: 0 };
    let tree = p.expr()?;
    if p.i != p.t.len() {
        return syntax();
    }
    let (r, d) = ev(&tree)?;
    let zero: Dims = [0; ND];
    if target == "-" {
        if d != zero {
            return Err("dimension".to_string());
        }
        return Ok(fmt(r));
    }
    let (f, td) = unit(target)?;
    if td != d {
        return Err("dimension".to_string());
    }
    Ok(format!("{} {}", fmt(r.div(f)), target))
}

/// Evaluates `expr` and renders it in the target unit (`-` for a plain number).
pub fn calc(expr: &str, target: &str) -> String {
    match run(expr, target) {
        Ok(s) => s,
        Err(e) => format!("error: {}", e),
    }
}

